"sandbox": {
  "enabled": true,
  "allowUnsandboxedCommands": false,
  "failIfUnavailable": true,
  "filesystem": { "allowWrite": ["<your worktrees dir>"] },
  "network": { "allowedDomains": ["github.com", "registry.npmjs.org"] }
}

# Probe it: ask Claude to run this. It must fail
# (Operation not permitted on macOS, Read-only file system on WSL2).
touch ~/sandbox-probe
